-- # Lernfeld 5: Cyberphysische Systeme > ## Datenbanken > - Relationales Modell

INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Kann ein relationales Modell ohne Primärschlüssel effektiv funktionieren?', 2, '[{"text": "Nein", "correct": true, "because": "Primärschlüssel sichern Eindeutigkeit"}, {"text": "Ja", "correct": false, "because": "Ohne Eindeutigkeit fehlt Integrität"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist jede Tabelle in einem relationalen Modell zwingend mit einer anderen verknüpft?', 2, '[{"text": "Nein", "correct": true, "because": "Isolierte Tabellen sind möglich"}, {"text": "Ja", "correct": false, "because": "Verknüpfung nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Fremdschlüssel im relationalen Modell NULL-Werte enthalten?', 2, '[{"text": "Ja", "correct": true, "because": "NULL erlaubt, wenn nicht zwingend"}, {"text": "Nein", "correct": false, "because": "Optionalität ist möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das relationale Modell nur für strukturierte Daten geeignet?', 2, '[{"text": "Ja", "correct": true, "because": "Tabellen erfordern Struktur"}, {"text": "Nein", "correct": false, "because": "Unstrukturierte Daten unpassend"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein relationales Modell ohne Normalisierung effizient arbeiten?', 2, '[{"text": "Nein", "correct": true, "because": "Redundanzen erhöhen Ineffizienz"}, {"text": "Ja", "correct": false, "because": "Normalisierung optimiert"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Element ist im relationalen Modell für die Eindeutigkeit von Datensätzen verantwortlich?', 2, '[{"text": "Primärschlüssel", "correct": true, "because": "Identifiziert jede Zeile eindeutig"}, {"text": "Fremdschlüssel", "correct": false, "because": "Verknüpft Tabellen"}, {"text": "Index", "correct": false, "because": "Verbessert Suche"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaft im relationalen Modell ermöglicht Beziehungen zwischen Tabellen?', 3, '[{"text": "Fremdschlüssel", "correct": true, "because": "Verweist auf Primärschlüssel"}, {"text": "Attribut", "correct": false, "because": "Nur Datenfeld"}, {"text": "Tupel", "correct": false, "because": "Zeile, keine Beziehung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Normalisierungsstufe beseitigt transitive Abhängigkeiten?', 2, '[{"text": "3. Normalform", "correct": true, "because": "Entfernt indirekte Abhängigkeiten"}, {"text": "1. Normalform", "correct": false, "because": "Nur atomare Werte"}, {"text": "2. Normalform", "correct": false, "because": "Partielle Abhängigkeiten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Konzept im relationalen Modell stellt sicher, dass keine redundanten Daten gespeichert werden?', 2, '[{"text": "Normalisierung", "correct": true, "because": "Reduziert Redundanz"}, {"text": "Join", "correct": false, "because": "Verknüpft Tabellen"}, {"text": "View", "correct": false, "because": "Virtuelle Darstellung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Struktur im relationalen Modell repräsentiert eine Datenmenge?', 2, '[{"text": "Tabelle", "correct": true, "because": "Speichert Daten in Zeilen und Spalten"}, {"text": "Attribut", "correct": false, "because": "Einzelne Spalte"}, {"text": "Schema", "correct": false, "because": "Gesamtdesign"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten sind Kern des relationalen Modells?', 4, '[{"text": "Tabellen", "correct": true, "because": "Datenstruktur"}, {"text": "Primärschlüssel", "correct": true, "because": "Eindeutigkeit"}, {"text": "Fremdschlüssel", "correct": true, "because": "Beziehungen"}, {"text": "Programmiersprachen", "correct": false, "because": "Extern"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen ein relationales Modell effizient?', 3, '[{"text": "Normalisierung", "correct": true, "because": "Reduziert Redundanz"}, {"text": "Indizes", "correct": true, "because": "Schnellere Abfragen"}, {"text": "Unstrukturierte Daten", "correct": false, "because": "Nicht relational"}, {"text": "Integritätsregeln", "correct": true, "because": "Sichern Konsistenz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Operationen sind im relationalen Modell üblich?', 3, '[{"text": "Join", "correct": true, "because": "Verknüpft Tabellen"}, {"text": "Select", "correct": true, "because": "Filtert Daten"}, {"text": "Compile", "correct": false, "because": "Nicht relational"}, {"text": "Project", "correct": true, "because": "Wählt Spalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können ohne Normalisierung im relationalen Modell auftreten?', 4, '[{"text": "Datenredundanz", "correct": true, "because": "Doppelte Daten"}, {"text": "Update-Anomalien", "correct": true, "because": "Inkonsistente Änderungen"}, {"text": "Schnelle Abfragen", "correct": false, "because": "Eher langsamer"}, {"text": "Lösch-Anomalien", "correct": true, "because": "Verlust von Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale unterscheiden relationale von NoSQL-Modellen?', 3, '[{"text": "Tabellen vs. flexible Strukturen", "correct": true, "because": "Schema vs. Schemalos"}, {"text": "ACID vs. BASE", "correct": true, "because": "Konsistenzansätze"}, {"text": "Keine Unterschiede", "correct": false, "because": "Klar unterschiedlich"}, {"text": "SQL-Unterstützung", "correct": true, "because": "Relational nutzt SQL"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Ein Primärschlüssel kann mehrere Spalten umfassen. b) Fremdschlüssel müssen immer ausgefüllt sein.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zusammengesetzter Schlüssel möglich, NULL erlaubt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Normalisierung erhöht die Abfragegeschwindigkeit immer. b) Tabellen im relationalen Modell sind zweidimensional.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Normalisierung kann verlangsamen, Tabellen 2D"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das relationale Modell unterstützt hierarchische Daten nativ. b) Integritätsregeln sind für Datenkonsistenz entscheidend.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Hierarchie ungeeignet, Regeln essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Ein Join verbindet Tabellen über Schlüssel. b) Das relationale Modell ist für unstrukturierte Daten ideal.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Join nutzt Schlüssel, unstrukturiert unpassend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das relationale Modell erfordert ein festes Schema. b) Indizes sind für jede Tabelle zwingend erforderlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schema fest, Indizes optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

